import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Controllers","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/controllers.md","filePath":"concepts/controllers.md"}'),i={name:"concepts/controllers.md"};function l(o,e,r,c,p,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="controllers" tabindex="-1">Controllers <a class="header-anchor" href="#controllers" aria-label="Permalink to &quot;Controllers&quot;">​</a></h1><p>Controllers are the rule engines of CCattler. Each controller watches specific fact prefixes, compares desired state against observed state, and proposes changes to close the gap. Controllers never call each other — they communicate exclusively through the fact store.</p><h2 id="instance-controller" tabindex="-1">Instance controller <a class="header-anchor" href="#instance-controller" aria-label="Permalink to &quot;Instance controller&quot;">​</a></h2><p>Maintains the correct number of running instances for each service.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desired=3, actual=1 → create 2 instances</span></span>
<span class="line"><span>desired=3, actual=5 → remove 2 instances</span></span></code></pre></div><p>The controller doesn&#39;t know why the desired count is 3 — it could be a user declaration, an autoscaler recommendation, or a policy override.</p><h2 id="endpoint-controller" tabindex="-1">Endpoint controller <a class="header-anchor" href="#endpoint-controller" aria-label="Permalink to &quot;Endpoint controller&quot;">​</a></h2><p>Derives network endpoints from running instances. When an instance transitions to <code>running</code> with a health state of <code>ready</code>, the endpoint controller creates an endpoint fact:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>instance a8f31 (running, ready, ip=10.1.0.5, port=8080)</span></span>
<span class="line"><span>→ endpoint(web, a8f31, 10.1.0.5:8080)</span></span></code></pre></div><p>Readiness-gated: only instances with <code>readiness=ready</code> (or no readiness probe configured) appear in endpoint sets.</p><h2 id="failure-controller" tabindex="-1">Failure controller <a class="header-anchor" href="#failure-controller" aria-label="Permalink to &quot;Failure controller&quot;">​</a></h2><p>Detects failed instances and nodes, triggers replacements.</p><ul><li><strong>Instance failure</strong> — if <code>instance.state = failed</code>, create a replacement</li><li><strong>Node failure</strong> — if <code>node.state = unreachable</code> (lease expired), all instances on that node need rescheduling</li></ul><h2 id="init-controller" tabindex="-1">Init controller <a class="header-anchor" href="#init-controller" aria-label="Permalink to &quot;Init controller&quot;">​</a></h2><p>Manages initialization lifecycle for services with <code>init</code> blocks. Init steps run sequentially before the main workload starts:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        exec </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;db-migrate --run&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        timeout 30s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        retry </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        exec </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cache-warm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        timeout 10s</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The controller tracks per-instance init phase: <code>pending → running → complete</code> (or <code>failed</code>). The main container starts only after all init steps succeed.</p><h2 id="autoscaling-engine" tabindex="-1">Autoscaling engine <a class="header-anchor" href="#autoscaling-engine" aria-label="Permalink to &quot;Autoscaling engine&quot;">​</a></h2><p>A unified engine with four input signals:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Example</th><th>How it works</th></tr></thead><tbody><tr><td><strong>CPU/memory</strong></td><td><code>target cpu = 60%</code></td><td>Scale when average exceeds threshold</td></tr><tr><td><strong>Custom metrics</strong></td><td><code>target requests_per_second = 500</code></td><td>Scale on application metrics</td></tr><tr><td><strong>Event-driven</strong></td><td><code>event payments.pending = 20</code></td><td>Queue depth / target = instances</td></tr><tr><td><strong>Scheduled</strong></td><td><code>schedule { weekdays 08:00-18:00, minimum 10 }</code></td><td>Time-based minimum</td></tr></tbody></table><p>Multiple metrics evaluated independently: <code>desired = max(cpu_rec, mem_rec, rps_rec, queue_rec, scheduled_min)</code>.</p><p>Stabilization windows prevent oscillation: scale-up stabilization = 60s, scale-down stabilization = 5m.</p><h2 id="rolling-update-controller" tabindex="-1">Rolling update controller <a class="header-anchor" href="#rolling-update-controller" aria-label="Permalink to &quot;Rolling update controller&quot;">​</a></h2><p>When a service&#39;s image changes, the update controller orchestrates a gradual rollout:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desired: 10 × nginx:1.28</span></span>
<span class="line"><span>actual:  10 × nginx:1.27</span></span>
<span class="line"><span></span></span>
<span class="line"><span>update_strategy { max_unavailable 1, max_extra 1 }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ start one 1.28 instance</span></span>
<span class="line"><span>→ wait until healthy</span></span>
<span class="line"><span>→ stop one 1.27 instance</span></span>
<span class="line"><span>→ repeat</span></span></code></pre></div><p>If new instances fail health checks beyond a threshold, the controller reverts the desired image — automatic rollback.</p><h2 id="how-controllers-communicate" tabindex="-1">How controllers communicate <a class="header-anchor" href="#how-controllers-communicate" aria-label="Permalink to &quot;How controllers communicate&quot;">​</a></h2><p>Controllers never import or call each other. Communication flows through state:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User applies config</span></span>
<span class="line"><span>  → desired/service/web/instances = 3</span></span>
<span class="line"><span>    → Instance controller creates 3 pending instances</span></span>
<span class="line"><span>      → Scheduler places them on nodes</span></span>
<span class="line"><span>        → Node agents start containers</span></span>
<span class="line"><span>          → Agents report observed state</span></span>
<span class="line"><span>            → Endpoint controller creates endpoints</span></span>
<span class="line"><span>              → DNS resolves service name to endpoints</span></span></code></pre></div><p>Each step is a different controller reacting to state changes. If any controller crashes, the next resync picks up where it left off.</p>`,30)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
